<?php

namespace App\Http\Controllers\Student;

use App\Http\Controllers\Controller;
use App\Models\Course;
use App\Models\Quiz;
use App\Models\QuizAttempt;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;

class QuizController extends Controller
{
    public function index(Request $request, Course $course) { $this->authorizeCourse($request,$course); $quizzes=$course->quizzes()->where('is_published',true)->withCount('questions')->with(['attempts'=>fn($q)=>$q->where('user_id',$request->user()->id)->where('status','submitted')->latest()])->get(); return view('student.quizzes.index',compact('course','quizzes')); }
    public function show(Request $request, Course $course, Quiz $quiz) { abort_unless($quiz->course_id===$course->id && $quiz->is_published,404); $this->authorizeCourse($request,$course); $quiz->load('questions'); $attempts=$request->user()->quizAttempts()->where('quiz_id',$quiz->id)->where('status','submitted')->latest()->get(); $inProgress=$request->user()->quizAttempts()->where('quiz_id',$quiz->id)->where('status','in_progress')->latest()->first(); return view('student.quizzes.show',compact('course','quiz','attempts','inProgress')); }
    public function start(Request $request, Course $course, Quiz $quiz) { abort_unless($quiz->course_id===$course->id && $quiz->is_published,404); $this->authorizeCourse($request,$course); abort_if($quiz->questions()->count()===0,422,'This quiz has no questions yet.'); $user=$request->user(); $active=$user->quizAttempts()->where('quiz_id',$quiz->id)->where('status','in_progress')->latest()->first(); if($active && $active->started_at->addMinutes($quiz->duration_minutes)->isFuture()) return redirect()->route('student.quizzes.take',[$course,$quiz,$active]); if($active) $this->grade($active,$quiz,[]); $count=$user->quizAttempts()->where('quiz_id',$quiz->id)->where('status','submitted')->count(); abort_if($count >= $quiz->attempts_allowed,403,'You have used all attempts for this quiz.'); $attempt=QuizAttempt::create(['quiz_id'=>$quiz->id,'user_id'=>$user->id,'attempt_number'=>$count+1,'started_at'=>now(),'status'=>'in_progress']); return redirect()->route('student.quizzes.take',[$course,$quiz,$attempt]); }
    public function take(Request $request, Course $course, Quiz $quiz, QuizAttempt $attempt) { abort_unless($quiz->course_id===$course->id && $attempt->quiz_id===$quiz->id && $attempt->user_id===$request->user()->id && $attempt->status==='in_progress',404); $this->authorizeCourse($request,$course); if($attempt->started_at->addMinutes($quiz->duration_minutes)->isPast()){ $this->grade($attempt,$quiz,$attempt->answers??[]); return redirect()->route('student.quizzes.result',[$course,$quiz,$attempt]); } $questions=$quiz->questions()->get(); $deadline=$attempt->started_at->copy()->addMinutes($quiz->duration_minutes); return view('student.quizzes.take',compact('course','quiz','attempt','questions','deadline')); }
    public function submit(Request $request, Course $course, Quiz $quiz, QuizAttempt $attempt) { abort_unless($quiz->course_id===$course->id && $attempt->quiz_id===$quiz->id && $attempt->user_id===$request->user()->id && $attempt->status==='in_progress',404); $this->authorizeCourse($request,$course); $raw=$request->input('answers',[]); abort_unless(is_array($raw),422); $safe=[]; foreach($quiz->questions as $question){ $value=$raw[$question->id]??null; if(is_numeric($value) && (int)$value>=0 && (int)$value<count($question->options)) $safe[$question->id]=(int)$value; } $this->grade($attempt,$quiz,$safe); return redirect()->route('student.quizzes.result',[$course,$quiz,$attempt])->with('success','Your quiz has been submitted and scored.'); }
    public function result(Request $request, Course $course, Quiz $quiz, QuizAttempt $attempt) { abort_unless($quiz->course_id===$course->id && $attempt->quiz_id===$quiz->id && $attempt->user_id===$request->user()->id && $attempt->status==='submitted',404); $this->authorizeCourse($request,$course); $questions=$quiz->questions()->get(); return view('student.quizzes.result',compact('course','quiz','attempt','questions')); }
    private function grade(QuizAttempt $attempt, Quiz $quiz, array $answers): void { DB::transaction(function() use($attempt,$quiz,$answers){ $score=0;$total=0;foreach($quiz->questions as $q){$total+=$q->points;if(isset($answers[$q->id]) && (int)$answers[$q->id]===$q->correct_option)$score+=$q->points;} $pct=$total>0?round($score*100/$total,2):0; $attempt->update(['answers'=>$answers,'score_points'=>$score,'total_points'=>$total,'percentage'=>$pct,'passed'=>$pct >= $quiz->passing_percentage,'submitted_at'=>now(),'status'=>'submitted']); }); }
    private function authorizeCourse(Request $request,Course $course): void { $active=$request->user()->enrollments()->where('course_id',$course->id)->where('status','active')->exists(); abort_unless($active,403,'An active enrolment is required to take course quizzes.'); }
}
